toolCalls.args:
{"command":"$lines = Get-Content .\input\session.jsonl
foreach ($l in $lines) {
  $j = $l | ConvertFrom-Json
  $t = $j.type
  if ($j.payload.type) { $t = $t + '/' + $j.payload.type }
  $role = ''
  if ($j.payload.role) { $role = $j.payload.role }
  $snippet = ''
  if ($j.payload.text) { $snippet = ($j.payload.text -join ' ') }
  elseif ($j.payload.name) { $snippet = $j.payload.name }
  elseif ($j.payload.output) { $snippet = $j.payload.output }
  elseif ($j.payload.summary) { $snippet = $j.payload.summary }
  if ($snippet.Length -gt 200) { $snippet = $snippet.Substring(0,200) + '...' }
  "$($j.ordinal)`t$t`trole=$role`t$snippet"
}"}

{"command":"[Console]::OutputEncoding = [System.Text.Encoding]::UTF8
Write-Output '--- HEAD file ---'; Get-Content .\workspace\.git\HEAD
Write-Output '--- packed-refs ---'; Get-Content .\workspace\.git\packed-refs -ErrorAction SilentlyContinue
Write-Output '--- refs heads ---'; Get-ChildItem .\workspace\.git\refs\heads -ErrorAction SilentlyContinue | ForEach-Object { $_.Name + ' ' + (Get-Content $_.FullName) }
Write-Output '--- log HEAD (top 20) ---'; Get-Content .\workspace\.git\logs\HEAD -ErrorAction SilentlyContinue | Select-Object -Last 20"}
